+                            }
+
+                            @Override
+                            public void onFailure(Exception e) {
+                                multipartUploadCleanupListener.onFailure(e);
+                                snapshotDeleteListener.onFailure(e);
+                            }
+                        }
+                    );
+                }
+
+                @Override
+                public void onFailure(Exception e) {
